import backtrader as bt


class IntradayBreakoutStrategy(bt.Strategy):
    def __init__(self):
        self.bb = bt.indicators.BollingerBands(
            self.data.close, period=20, devfactor=2.0
        )
        self.atr = bt.indicators.ATR(self.data, period=14)
        self.band_width = self.bb.top - self.bb.bot
        self.squeeze_threshold = bt.indicators.SMA(self.band_width, period=20)
        self.cross_top = bt.indicators.CrossOver(self.data.close, self.bb.top)
        self.cross_bottom = bt.indicators.CrossOver(self.data.close, self.bb.bot)

        self.order = None
        self.stop_order = None

    def notify_order(self, order):
        if order.status in [order.Completed, order.Canceled, order.Margin, order.Rejected]:
            if order == self.order:
                self.order = None

            if order == self.stop_order:
                self.stop_order = None
                return

            if order.status == order.Completed and order.info.get("role") == "entry":
                stop_distance = 2.0 * self.atr[0]
                if order.isbuy():
                    self.stop_order = self.sell(
                        size=order.executed.size,
                        exectype=bt.Order.Stop,
                        price=order.executed.price - stop_distance,
                    )
                else:
                    self.stop_order = self.buy(
                        size=abs(order.executed.size),
                        exectype=bt.Order.Stop,
                        price=order.executed.price + stop_distance,
                    )

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.stop_order:
                return

            if self.band_width[0] < self.squeeze_threshold[0]:
                if self.cross_top[0] > 0:
                    self.order = self.buy()
                    self.order.addinfo(role="entry")
                elif self.cross_bottom[0] < 0:
                    self.order = self.sell()
                    self.order.addinfo(role="entry")
        elif self.position.size > 0 and self.cross_top[0] < 0:
            if self.stop_order:
                self.cancel(self.stop_order)
            self.order = self.close()
            self.order.addinfo(role="exit")
        elif self.position.size < 0 and self.cross_bottom[0] > 0:
            if self.stop_order:
                self.cancel(self.stop_order)
            self.order = self.close()
            self.order.addinfo(role="exit")
